/**
 * AeroBridge Studio — Demo Mode (development only)
 *
 * Simulates the Tauri desktop backend inside a regular browser so the full native UI
 * (drive tree, Commander, terminal, notepad) can be presented and screenshotted
 * without touching the real file system.
 *
 * Enable with `npm run dev` + `http://localhost:3000/?demo`.
 * Optional query params: `dir=<path>` (browser folder), `left=<path>` / `right=<path>` (Commander panes).
 *
 * The virtual file system is generated by `scripts/demo/build_demo_fs.py` into `demo/fs/`.
 * Its files are real PSD / BLEND / FIG / KRA / AI / INDD / PDF / HTML files, so every preview
 * on screen is produced by the app's own extractors — only the OS layer is simulated.
 */

import { mockIPC, mockWindows } from '@tauri-apps/api/mocks';
import { emit } from '@tauri-apps/api/event';

interface ManifestFile {
  file: string;
  alias?: string;
  size: number;
  modified_ms: number;
}

interface DemoManifest {
  drives: { letter: string; name: string }[];
  places: { name: string; path: string }[];
  files: ManifestFile[];
}

interface DemoEntry {
  name: string;
  path: string;
  size: number;
  is_dir: boolean;
  modified_ms: number;
  extension: string;
  url?: string;
}

const FS_BASE = '/demo/fs/';

const norm = (p: string) => p.replace(/\//g, '\\').replace(/\\+$/, '').toLowerCase();

const toVirtual = (file: string) => {
  const [drive, ...rest] = file.split('/');
  return `${drive}:\\${rest.join('\\')}`;
};

const toUrl = (file: string) => FS_BASE + file.split('/').map(encodeURIComponent).join('/');

function buildTree(manifest: DemoManifest) {
  const entries = new Map<string, DemoEntry>();
  const children = new Map<string, DemoEntry[]>();

  const ensureDir = (path: string, modified: number) => {
    const key = norm(path);
    if (!key.includes('\\') || entries.has(key)) return;
    const parent = path.slice(0, path.lastIndexOf('\\'));
    const dir: DemoEntry = {
      name: path.slice(path.lastIndexOf('\\') + 1),
      path,
      size: 0,
      is_dir: true,
      modified_ms: modified,
      extension: '',
    };
    entries.set(key, dir);
    ensureDir(parent, modified);
    const parentKey = norm(parent);
    if (!children.has(parentKey)) children.set(parentKey, []);
    children.get(parentKey)!.push(dir);
  };

  for (const f of manifest.files) {
    const path = toVirtual(f.file);
    const name = path.slice(path.lastIndexOf('\\') + 1);
    const parent = path.slice(0, path.lastIndexOf('\\'));
    ensureDir(parent, f.modified_ms);
    const entry: DemoEntry = {
      name,
      path,
      size: f.size,
      is_dir: false,
      modified_ms: f.modified_ms,
      extension: name.includes('.') ? name.split('.').pop()!.toLowerCase() : '',
      url: toUrl(f.alias ?? f.file),
    };
    entries.set(norm(path), entry);
    const parentKey = norm(parent);
    if (!children.has(parentKey)) children.set(parentKey, []);
    children.get(parentKey)!.push(entry);
  }
  return { entries, children };
}

const strip = ({ url: _url, ...rest }: DemoEntry) => rest;

// ---------------------------------------------------------------- simulated terminal

const ESC = '\x1b[';
const c = (code: string, s: string) => `${ESC}${code}m${s}${ESC}0m`;

function promptFor(cwd: string, shell: string) {
  if (shell === 'cmd') return `${cwd}>`;
  if (shell === 'wsl') return `${c('1;32', 'studio@nova')}:${c('1;34', '/mnt/' + cwd[0].toLowerCase() + cwd.slice(2).replace(/\\/g, '/'))}$ `;
  return `${c('32', 'PS')} ${cwd}> `;
}

const SCRIPTED_SESSION: { cmd: string; out: string }[] = [
  {
    cmd: 'git log --oneline -5',
    out: [
      `${c('33', 'a41c9e2')} ${c('36', '(HEAD -> main, origin/main)')} art: transit tunnel lighting pass v02`,
      `${c('33', '7be03d1')} key-art: B1 poster v07 – final typography`,
      `${c('33', '19f4a6c')} vehicles: pod racer turnaround + blend preview`,
      `${c('33', 'c2d8e90')} ui: inventory weight indicator states (figma + html)`,
      `${c('33', '5e71b3a')} characters: orange pilot final paint-over`,
    ].join('\r\n'),
  },
  {
    cmd: 'Get-ChildItem .\\04_Key_Art_Marketing',
    out: [
      '',
      `    ${c('32', 'Directory:')} F:\\NOVA_EXODUS\\04_Key_Art_Marketing`,
      '',
      `${c('32', 'Mode                 LastWriteTime         Length Name')}`,
      `${c('32', '----                 -------------         ------ ----')}`,
      '-a---          14.10.2026    15:54      149527142 NOVA_ArtBook_Ch03_Spread.indd',
      '-a---          11.10.2026    16:57       25270681 NOVA_Pitch_Deck.pdf',
      '-a---          13.10.2026    08:04       40580300 NOVA_Poster_B1.ai',
      '-a---          08.10.2026    14:12       67423846 NOVA_PressKit_A4.indd',
      '-a---          07.10.2026    08:10      163997286 NOVA_Steam_Capsule.psd',
      '-a---          30.09.2026    08:01      221042278 NOVA_Trailer_Storyboard.psd',
      '',
    ].join('\r\n'),
  },
  {
    cmd: 'Get-ChildItem -Recurse -Include *.psd,*.blend,*.indd | Measure-Object Length -Sum',
    out: [
      '',
      `Count    : ${c('1;37', '18')}`,
      `Sum      : ${c('1;37', '5 912 348 160')}`,
      'Property : Length',
      '',
    ].join('\r\n'),
  },
];

function scheduleTerminal(id: string, cwd: string, shell: string) {
  const send = (data: string) => void emit(`pty-data-${id}`, { data });
  let t = 120;
  const at = (ms: number, fn: () => void) => setTimeout(fn, (t += ms));

  if (shell === 'powershell') {
    at(0, () => send(`PowerShell 7.5.2\r\n${c('90', 'Loading personal and system profiles took 412ms.')}\r\n`));
  }
  at(150, () => send(promptFor(cwd, shell)));
  for (const step of SCRIPTED_SESSION) {
    for (const ch of step.cmd) at(18, () => send(ch));
    at(220, () => send(`\r\n${step.out}\r\n`));
    at(160, () => send(promptFor(cwd, shell)));
  }
}

// ---------------------------------------------------------------- install

export async function installDemoMode(): Promise<void> {
  const manifest: DemoManifest = await fetch(FS_BASE + 'manifest.json').then((r) => {
    if (!r.ok) throw new Error('Demo FS missing – run: python scripts/demo/build_demo_fs.py');
    return r.json();
  });
  const { entries, children } = buildTree(manifest);
  const textEdits = new Map<string, string>();
  const ptyInput = new Map<string, { line: string; cwd: string; shell: string }>();

  const urlOf = (path: string) => entries.get(norm(path))?.url;
  const listDir = (path: string) => (children.get(norm(path)) ?? []).map(strip);
  const folderSize = (path: string) => {
    let total = 0, files = 0, folders = 0;
    const walk = (p: string) => {
      for (const e of listDir(p)) {
        if (e.is_dir) { folders++; walk(e.path); } else { files++; total += e.size; }
      }
    };
    walk(path);
    return { total_bytes: total, file_count: files, folder_count: folders };
  };
  const readBinary = async (path: string, maxBytes?: number | null) => {
    const url = urlOf(path);
    if (!url) throw new Error(`Soubor nenalezen: ${path}`);
    const buf = await fetch(url).then((r) => r.arrayBuffer());
    return maxBytes && buf.byteLength > maxBytes ? buf.slice(0, maxBytes) : buf;
  };

  // Seed UI state (query params win over remembered paths)
  const params = new URLSearchParams(location.search);
  const seed = (key: string, value: string | null) => {
    if (value) localStorage.setItem(key, value);
  };
  seed('aerobridge_last_native_dir', params.get('dir') ?? 'F:\\NOVA_EXODUS\\01_Concept_Art');
  seed('aerobridge_commander_left_path', params.get('left') ?? 'F:\\NOVA_EXODUS');
  seed('aerobridge_commander_right_path', params.get('right') ?? 'F:\\NOVA_EXODUS\\05_UI_HUD');

  // Notepad tabs in both Commander panes: project docs from the demo drive
  const docs = ['F:\\NOVA_EXODUS\\Lore_Bible.md', 'F:\\NOVA_EXODUS\\Asset_Pipeline.md', 'F:\\NOVA_EXODUS\\build_manifest.json'];
  const tabs = await Promise.all(
    docs.map(async (filePath, i) => ({
      id: `demo_tab_${i}`,
      title: filePath.split('\\').pop(),
      filePath,
      content: new TextDecoder().decode(await readBinary(filePath)),
      isDirty: false,
    }))
  );
  for (const pane of ['left', 'right']) {
    if (!localStorage.getItem(`aerobridge_commander_notepad_tabs_${pane}`)) {
      localStorage.setItem(`aerobridge_commander_notepad_tabs_${pane}`, JSON.stringify(tabs));
      localStorage.setItem(`aerobridge_commander_notepad_active_tab_${pane}`, tabs[0].id);
    }
  }

  (globalThis as unknown as { isTauri: boolean }).isTauri = true;
  mockWindows('main');

  mockIPC(
    async (cmd, raw) => {
      const args = (raw ?? {}) as Record<string, any>;
      switch (cmd) {
        case 'list_drives':
          return manifest.drives.map((d) => ({ name: d.name, path: `${d.letter}:\\` }));
        case 'get_user_places':
          return manifest.places;
        case 'scan_folder_native':
          return listDir(args.path);
        case 'list_subdirs':
          return listDir(args.path).filter((e) => e.is_dir);
        case 'read_file_binary':
          return readBinary(args.path, args.maxBytes);
        case 'read_file_range': {
          const buf = await readBinary(args.path);
          return buf.slice(args.offset, args.offset + args.length);
        }
        case 'get_folder_size':
          return folderSize(args.path);
        case 'read_text_file_native': {
          const key = norm(args.path);
          if (textEdits.has(key)) return textEdits.get(key);
          return new TextDecoder().decode(await readBinary(args.path));
        }
        case 'write_text_file_native':
          textEdits.set(norm(args.path), args.content);
          return null;

        // No OS shell handlers in the demo: the app falls back to its own format parsers.
        case 'extract_xmp_thumbnail':
          return null;
        case 'extract_embedded_jpeg':
        case 'get_shell_thumbnail':
        case 'get_file_icon':
          return new ArrayBuffer(0);

        case 'get_associated_apps_native':
          return [
            { name: 'Adobe Photoshop 2026', exe_name: 'Photoshop.exe', path: null, is_default: true },
            { name: 'Krita', exe_name: 'krita.exe', path: null, is_default: false },
            { name: 'Blender 4.5', exe_name: 'blender.exe', path: null, is_default: false },
          ];

        case 'pty_spawn': {
          const cwd = args.cwd || 'F:\\NOVA_EXODUS';
          ptyInput.set(args.id, { line: '', cwd, shell: args.shell || 'powershell' });
          scheduleTerminal(args.id, cwd, args.shell || 'powershell');
          return null;
        }
        case 'pty_write': {
          const s = ptyInput.get(args.id);
          if (!s) return null;
          const send = (data: string) => void emit(`pty-data-${args.id}`, { data });
          for (const ch of String(args.data)) {
            if (ch === '\r') {
              const cmdLine = s.line.trim();
              s.line = '';
              const out = cmdLine
                ? `\r\n${c('90', '[demo] Příkazy se v ukázkovém režimu nespouštějí.')}\r\n`
                : '\r\n';
              send(out + promptFor(s.cwd, s.shell));
            } else if (ch === '\x7f') {
              if (s.line) { s.line = s.line.slice(0, -1); send('\b \b'); }
            } else if (ch >= ' ') {
              s.line += ch;
              send(ch);
            }
          }
          return null;
        }
        case 'pty_resize':
        case 'pty_kill':
          return null;

        case 'execute_shell_command_native':
          return { stdout: '', stderr: 'Ukázkový režim: příkazy se nespouštějí.', exit_code: 1, success: false };

        case 'rename_file_native':
        case 'create_folder_native':
        case 'delete_files_native':
        case 'copy_files_native':
        case 'move_files_native':
          throw new Error('Ukázkový režim je jen pro čtení.');

        default:
          return null;
      }
    },
    { shouldMockEvents: true }
  );

  (window as any).__TAURI_INTERNALS__.convertFileSrc = (filePath: string) => urlOf(filePath) ?? '';
  document.title = 'AeroBridge Studio — Demo';
}
